// Chatwoot posts here now, not Meta. One item, one event.
const item = $input.first().json;
const q    = item.query   || {};
const body = item.body    || {};

const SHARED = "<N8N_WEBHOOK_SECRET — redacted, value is in .env>";

// --- Is this actually from Chatwoot? --------------------------------------
// Chatwoot DOES sign its webhooks (X-Chatwoot-Signature, HMAC-SHA256 over
// `${timestamp}.${body}`), but verifying that here is not currently possible:
// require('crypto') throws "Module 'crypto' is disallowed" in this task-runner
// sandbox, and the Crypto node cannot prepend a timestamp to the RAW bytes -
// re-serialising the parsed body does not reproduce them. So the door is a
// secret in the query string, which the agent bot's outgoing_url carries.
//
// Fails CLOSED, and answers 200 either way: a caller who is not Chatwoot must
// learn nothing from the response.
if (String(q.s || '') !== SHARED) {
  return [{ json: { _reply: '', _work: false, _rejected: 'bad secret' } }];
}

// --- Which events are ours ------------------------------------------------
// Everything on this inbox arrives at this one URL: message_created,
// message_updated, conversation_status_changed, and the bot's OWN outgoing
// messages. Answering that last one is an infinite loop.
if (body.event !== 'message_created') {
  return [{ json: { _reply: '', _work: false } }];
}
// --- A human replied: that IS the takeover --------------------------------
// Chatwoot does not assign a conversation to the agent who answers it (its
// self_assign? is only a notification check), so an agent who replied and
// walked away would still have the bot talking over them. The workflow closes
// that gap: a public reply from a person assigns them the conversation, which
// trips the switch above on the resident's next message, and the 15-minute
// handback takes it from there.
//
// The bot's own replies arrive here too, as sender.type 'agent_bot' -- claiming
// on those would assign the bot's messages to nobody and loop. Private notes
// are excluded on purpose: writing an internal note is not claiming.
if (body.message_type === 'outgoing'
    && body.private !== true
    && (body.sender || {}).type === 'user') {
  return [{ json: { _reply: '', _work: false, _claim: true,
                    conv_id: (body.conversation || {}).id,
                    claim_user: (body.sender || {}).id } }];
}

if (body.message_type !== 'incoming' || body.private === true) {
  return [{ json: { _reply: '', _work: false } }];
}

const conv   = body.conversation || {};
const convId = conv.id;

// --- The on/off switch ----------------------------------------------------
// The bot answers by DEFAULT. Three things turn it off, for one conversation
// and no other, and every one of them is a visible act in the inbox rather
// than a hidden flag an agent cannot see:
//
//   assigned to somebody  - taking a conversation is taking it over
//   labelled `bot-off`    - the explicit switch: one click, shows as a chip
//   resolved              - the conversation is finished
//
// `status === 'pending'` was the signal until 21 Aug and it was the wrong one.
// It is Chatwoot's bot-owned state, and the default conversation list HIDES it,
// so every thread the bot was working was invisible and the inbox read as
// empty. The rule below is the same capability aimed at something an agent can
// actually see and click.
//
// Auto-assignment is OFF on inbox 1 and must stay off. With it on, Chatwoot
// assigns an agent the moment a conversation arrives, and the first test above
// silences the bot before it has said anything.
// Chatwoot assigns every NEW conversation on a bot inbox to the AGENT BOT
// ITSELF (meta.assignee_type 'AgentBot') -- found 23 Aug, when the bot fell
// silent on every conversation created after it was linked. Being assigned to
// yourself is not a human takeover. Only a User assignee is; the bot object
// also carries outgoing_url, which a person never does, hence the fallback.
const assignee = (conv.meta || {}).assignee;
const aType    = (conv.meta || {}).assignee_type;
const humanHasIt = !!assignee &&
  (aType ? aType === 'User' : !assignee.outgoing_url);
const labels   = conv.labels || [];
if (humanHasIt || labels.includes('bot-off') || conv.status === 'resolved') {
  return [{ json: { _reply: '', _work: false, _handedOver: true } }];
}

// Chatwoot sends E.164 with a plus; Meta sent bare digits. Everything
// downstream - both Supabase writers, every tool, and 99 existing rows -
// matches the bare form, so it is normalised here and nowhere else.
const sender = body.sender || {};
const from   = String(sender.phone_number || '').replace(/^\+/, '');
const id     = String(body.id || '');
const text   = String(body.content || '');

// --- Duplicate suppression ------------------------------------------------
// On Chatwoot's message id now rather than Meta's wamid. Same reasoning:
// stable across retries, and never on content, because a resident who sends
// the same word twice means it twice.
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const now = Date.now();
for (const k of Object.keys(store.seen)) {
  if (now - store.seen[k] > 86400000) delete store.seen[k];
}
if (store.seen[id]) {
  return [{ json: { _reply: '', _work: false } }];
}
store.seen[id] = now;

const lang = 'he';
const inText = text.trim() ? text : null;

// --- Has this handset already been spoken to? -----------------------------
// Unchanged in purpose: the menu and the canned lines never reach the model,
// so without this the agent introduces itself a second time to someone it has
// already greeted.
store.greeted = store.greeted || {};
// A person greets again after a day of silence — and so does Michael. The
// value is the last time this phone wrote; anything that is not a number is
// the old boolean format and counts as stale, so every existing contact gets
// the new introduction once.
const lastSeen = store.greeted[from];
const greeted = typeof lastSeen === 'number' && (Date.now() - lastSeen) < 24 * 60 * 60 * 1000;
store.greeted[from] = Date.now();

// Three items, so Chatwoot renders reply buttons rather than a list. Four or
// more silently becomes a list whose wrapper button reads "Choose an item" in
// English. `content` and `items` are Chatwoot's field names: it builds the
// WhatsApp payload itself, and drops anything it has no field for - which is
// where the old row descriptions and footer went.
const MENU = {
  content: "היי, כאן שירות הלקוחות של הומיז. במה אפשר לעזור?",
  items: [
    { title: "פתיחת קריאת שירות", value: "open" },
    { title: "מצב קריאה קיימת",   value: "status" },
    { title: "לדבר עם נציג",      value: "human" },
  ],
};

// Media, location and stickers arrive as an attachment with empty content.
if (!text.trim()) {
  return [{ json: {
    _reply: '', _work: false, _canned: true, _menu: false,
    to: from, conv_id: convId, lang,
    text: "אני קורא כאן רק טקסט. אפשר לכתוב לי מה קרה?",
    in_text: inText, msg_type: 'attachment', message_id: id,
  } }];
}

// --- A tapped button ------------------------------------------------------
// Chatwoot discards the button's id and forwards only its TITLE, so these
// strings ARE the routing table. Keep them identical to MENU above: reword one
// there and the flow it starts silently stops starting, falling through to the
// model instead of failing loudly.
const TAPPED = {
  "פתיחת קריאת שירות": "בסדר. מה התקלה?",
  "מצב קריאה קיימת":   "מה מספר הקריאה? אפשר גם רק את הספרות האחרונות — ואם אין מספר, בניין ודירה.",
};
const canned = TAPPED[text.trim()];
if (canned) {
  return [{ json: {
    _reply: '', _work: false, _canned: true, _menu: false,
    to: from, conv_id: convId, lang, text: canned,
    in_text: inText, msg_type: 'interactive', message_id: id,
  } }];
}

// "לדבר עם נציג" is deliberately absent above: it falls through to the agent,
// which calls transfer_to_human and says the right thing on the way out.


return [{ json: {
  _reply: '', _work: true, _canned: false, _menu: false,
  to: from, conv_id: convId, text, lang, greeted, message_id: id,
  in_text: inText, msg_type: 'text',
  followup: { content: "אפשר לעזור בעוד משהו?", items: MENU.items },
} }];

